#!/usr/bin/env python3
"""Frozen implementation of manifest PX02 v1; no network or random draws.

Usage: python run_analysis.py DATA_DIR OUTPUT_DIR [--influence SPEC_ID]
The exact supplied grid is embedded below, so the script is self-contained.
"""
import os

# Set before importing numerical libraries to avoid small-matrix thread overhead.
for _var in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS",
             "VECLIB_MAXIMUM_THREADS", "NUMEXPR_NUM_THREADS"):
    os.environ[_var] = "1"

import argparse
import hashlib
import importlib.metadata
import io
import json
import platform
import sys
import time
import traceback
from pathlib import Path

import numpy as np
import pandas as pd
from scipy import linalg, sparse, stats
from scipy.sparse.csgraph import connected_components

CONTROLS = ["population", "popdensity", "popmales", "households",
            "unemploymentrate", "income_householdmedian", "income_medianearnings",
            "income_percapita", "popeduc", "popyoungmales"]
LOG_CONTROLS = [c for c in CONTROLS if c not in ("popdensity", "unemploymentrate")]
RESULT_COLS = "spec_id analysis term status error n_obs n_counties n_dropped_missing estimate se_cluster p_cluster df_cluster se_hc1 p_hc1 df_hc1 ci_low ci_high r2 k_slopes sample_hash".split()
TABLE_COLS = {
    "an01_groups": "spec_id variable treated_mean control_mean difference n_treated n_control p_welch p_equal_variance".split(),
    "an02_summary": "spec_id variable mean std median min max n_nonmissing n_rows n_counties n_quarters".split(),
    "an09_membership": "spec_id fips treat boundary_B1 boundary_B2 timing".split(),
    "an09_counts": "spec_id sample treat n_counties".split(),
    "an10_means": "spec_id outcome quarter qidx treat mean_log1p mean_cumulative n_counties".split(),
    "placebo_vectors": "spec_id fips placebo_treat".split(),
}


def sample_hash(counties):
    return hashlib.sha256(",".join(str(int(c)) for c in sorted(set(counties))).encode()).hexdigest()


def transform(values, rule):
    x = np.asarray(values, dtype=float)
    with np.errstate(divide="ignore", invalid="ignore"):
        if rule == "G1":
            return np.log1p(x)
        if rule == "G2":
            return np.where(x == 0, 0.0, np.where(x > 0, np.log(x), np.nan))
    raise ValueError(f"Unknown log rule {rule}")


def groups(values, k):
    n = values.notna().sum()
    if not n:
        return values * np.nan
    return 1 + np.floor(k * (values.rank(method="min") - 1) / n)


def transformed_controls(frame, rule):
    result = frame[CONTROLS].copy()
    if rule == "L2":
        with np.errstate(invalid="ignore", divide="ignore"):
            result[LOG_CONTROLS] = np.log1p(result[LOG_CONTROLS])
    elif rule != "L1":
        raise ValueError(f"Unknown control rule {rule}")
    return result


class Data:
    def __init__(self, directory):
        directory = Path(directory)
        self.log = {"by_spec": {}}
        lookup = pd.read_csv(directory / "county_lookup.csv")
        self.log["lookup_rows_excluded_massachusetts"] = int((lookup.STATE_NAME == "Massachusetts").sum())
        self.u = lookup.loc[lookup.STATE_NAME != "Massachusetts", ["FIPS", "treat"]].rename(columns={"FIPS": "fips"})
        self.u["fips"] = self.u.fips.astype(int)
        self.u = self.u.set_index("fips").sort_index()
        if not self.u.index.is_unique or not self.u.treat.isin([0, 1]).all():
            raise ValueError("County universe must have unique FIPS and binary treatment")
        self.ids = self.u.index.to_numpy()
        self.log["universe_counties"] = len(self.u)

        raw = pd.read_csv(directory / "quarterly.csv", sep="\t", dtype=str, keep_default_na=False)
        self.log["quarterly_input_rows"] = len(raw)
        repeated = raw.geoid.eq("geoid")
        self.log["quarterly_removed_repeated_header"] = int(repeated.sum())
        raw = raw.loc[~repeated].copy()
        empty = raw.quarter.str.strip().eq("")
        counts = [c for c in raw if c not in ["geoid", "quarter"]]
        numeric = raw[counts].apply(pd.to_numeric, errors="coerce")
        invalid = numeric.isna().any(axis=1)
        self.log["quarterly_empty_quarter_including_overlap"] = int(empty.sum())
        self.log["quarterly_unparseable_counts_including_overlap"] = int(invalid.sum())
        self.log["quarterly_removed_empty_quarter"] = int(empty.sum())
        self.log["quarterly_removed_unparseable_counts_after_empty"] = int((invalid & ~empty).sum())
        self.log["quarterly_removed_total"] = int(repeated.sum() + (empty | invalid).sum())
        raw = raw.loc[~(empty | invalid)].copy()
        raw[counts] = numeric.loc[raw.index]
        raw["fips"] = pd.to_numeric(raw.geoid, errors="raise").astype(int)
        parsed = raw.quarter.str.extract(r"^(\d{4})q([1-4])$")
        if parsed.isna().any().any():
            raise ValueError("Unrecognized nonempty quarterly label")
        raw["qidx"] = (parsed[0].astype(int) - 1960) * 4 + parsed[1].astype(int) - 1
        qids = np.arange((2005 - 1960) * 4 + 1, (2014 - 1960) * 4 + 4)
        outside_u, outside_q = ~raw.fips.isin(self.ids), ~raw.qidx.isin(qids)
        self.log["quarterly_outside_universe"] = int(outside_u.sum())
        self.log["quarterly_outside_quarter_range"] = int(outside_q.sum())
        self.log["quarterly_unused_outside_universe_or_range"] = int((outside_u | outside_q).sum())
        raw = raw.loc[~(outside_u | outside_q)]
        if raw.duplicated(["fips", "qidx"]).any():
            raise ValueError("Duplicate county-quarter records")
        index = pd.MultiIndex.from_product([self.ids, qids], names=["fips", "qidx"])
        panel = raw.set_index(["fips", "qidx"])[counts].astype(float).reindex(index, fill_value=0).reset_index()
        panel["year"] = panel.qidx // 4 + 1960
        panel["quarter"] = panel.year.astype(str) + "q" + (panel.qidx % 4 + 1).astype(str)
        panel["post"] = (panel.year >= 2008).astype(int)
        panel["treat"] = panel.fips.map(self.u.treat)
        self.log["balanced_rows"] = len(panel)
        self.log["balanced_quarters"] = len(qids)
        self.log["balanced_zero_filled_rows"] = len(panel) - len(raw)
        self.log["low_own_O1_negative_cells"] = int((panel.totaloldfocused5 < panel.totaloldfocused1).sum())

        acs = pd.read_stata(directory / "acs5year.dta", convert_categoricals=False)
        acs["geo_fips"] = acs.geo_fips.astype(int)
        acs["acsyear"] = acs.acsyear.astype(int)
        if acs.duplicated(["geo_fips", "acsyear"]).any():
            raise ValueError("Duplicate ACS county-year records")
        acs[CONTROLS] = acs[CONTROLS].astype(float)
        latest = int(acs.acsyear.max())
        self.log["acs_latest_year"] = latest
        no_acs = sorted(set(self.ids) - set(acs.geo_fips))
        self.log["counties_without_any_acs_row"] = len(no_acs)
        self.log["county_keys_without_any_acs_row"] = no_acs
        self.log["panel_rows_without_any_acs_row"] = len(no_acs) * len(qids)
        targets = sorted(set(range(2005, 2015)) | {2008, 2011})
        nearest = {year: pd.DataFrame(np.nan, index=self.ids, columns=CONTROLS) for year in targets}
        for county, sub in acs.loc[acs.geo_fips.isin(self.ids)].groupby("geo_fips"):
            sub = sub.sort_values("acsyear")
            years = sub.acsyear.to_numpy()
            for year in targets:
                nearest[year].loc[county] = sub.iloc[np.argmin(np.abs(years - year))][CONTROLS].to_numpy(dtype=float)
        # Global latest-year cap is applied before the county nearest-year lookup.
        for year in range(2005, 2015):
            target = min(year, latest)
            if target not in nearest:
                frame = pd.DataFrame(np.nan, index=self.ids, columns=CONTROLS)
                for county, sub in acs.loc[acs.geo_fips.isin(self.ids)].groupby("geo_fips"):
                    sub = sub.sort_values("acsyear")
                    frame.loc[county] = sub.iloc[np.argmin(np.abs(sub.acsyear.to_numpy() - target))][CONTROLS].to_numpy(dtype=float)
                nearest[target] = frame
            mask = panel.year.eq(year)
            panel.loc[mask, CONTROLS] = nearest[target].reindex(panel.loc[mask, "fips"])[CONTROLS].to_numpy()
        self.panel = panel
        self.cross = {"Y1": nearest[2011], "Y2": nearest[2008],
                      "Y3": acs.groupby("geo_fips")[CONTROLS].mean().reindex(self.ids)}
        self.density_quartile = groups(self.cross["Y1"].popdensity, 4)
        self.density_decile = groups(self.cross["Y1"].popdensity, 10)

        boundary = pd.read_csv(directory / "boundary-counties.csv", dtype=str, keep_default_na=False)
        neighbors = {int(c): set() for c in self.ids}
        for source, adjacent in boundary.iloc[:, :2].itertuples(index=False, name=None):
            source = int(source)
            if source in neighbors:
                neighbors[source].update(int(n.strip()) for n in adjacent.split(";") if n.strip()
                                         and int(n.strip()) in neighbors and int(n.strip()) != source)
        opposite = {c: any(self.u.loc[n, "treat"] != self.u.loc[c, "treat"] for n in ns)
                    for c, ns in neighbors.items()}
        self.boundary = {
            "B1": set(c for c in self.ids if opposite[c]),
            "B2": set(c for c in self.ids if self.u.loc[c, "treat"] == 0 or opposite[c]),
        }
        timing = pd.read_excel(directory / "timing.xlsx", sheet_name=0, dtype={"FIPS": str})
        dates = pd.to_datetime(timing["Sch SB Delivery"], errors="coerce")
        timing_ids = pd.to_numeric(timing.FIPS, errors="coerce")
        self.timing = set(timing_ids.loc[dates.dt.year.isin([2005, 2006])].dropna().astype(int)) & set(self.ids)
        self.log["timing_counties_excluded_missing_date_or_absent"] = int(len(set(self.ids) - set(timing_ids.loc[dates.notna()].dropna().astype(int))))

        distance = pd.read_csv(directory / "distance.csv", sep="\t")
        distance["fips"] = distance.fips.astype(int)
        self.log["distance_rows_outside_universe"] = int((~distance.fips.isin(self.ids)).sum())
        distance = distance.loc[distance.fips.isin(self.ids)].copy()
        self.log["distance_rows_missing_either_distance_in_universe"] = int(distance[["ggl_distance", "osrm_distance"]].isna().any(axis=1).sum())
        distance = distance.dropna(subset=["ggl_distance", "osrm_distance"])
        lat1, lon1, lat2, lon2 = np.deg2rad(distance[["origin_lat", "origin_lon", "dest_lat", "dest_lon"]].to_numpy()).T
        h = np.sin((lat2 - lat1) / 2)**2 + np.cos(lat1) * np.cos(lat2) * np.sin((lon2 - lon1) / 2)**2
        distance["dist_km"] = 2 * 6371.0088 * np.arcsin(np.sqrt(np.clip(h, 0, 1)))
        distance["err"] = abs(distance.osrm_distance - distance.ggl_distance)
        self.distance = distance
        self.draws = pd.read_csv(directory / "placebo_draws.csv")
        self.draws["fips"] = self.draws.fips.astype(int)
        self._outcomes = {}

    def outcome(self, name, row):
        F, D, O = row.get("F") or "F1", row.get("D") or "D1", row.get("O") or "O1"
        key = (name, F, D, O)
        if key in self._outcomes:
            return self._outcomes[key]
        p = self.panel
        direct = {"total": "totalcontrib", "contributors": "totalusers", "new": "totalnewusers",
                  "old": "totaloldusers_active", "high_own": "totaloldfocused1", "owner": "totalowneredit"}
        if name in direct:
            result = p[direct[name]]
        elif name.startswith("pct"):
            result = p["totalpctcontrib" + name[3:]]
        elif name == "low_own":
            result = p.totaloldfocused5 if O == "O2" else (p.totaloldfocused5 - p.totaloldfocused1).where(p.totaloldfocused5 >= p.totaloldfocused1)
        else:
            tags = {"F1": ["totaltaga", "totaltagb", "totaltagh"],
                    "F2": ["totaltagv2a", "totaltagv2b", "totaltagv2h"],
                    "F3": ["totalversion2", "totalversion3", "totalversion4plus"],
                    "F4": ["totaltaga", "totaltagb", "totaltagh", "totaltagv2a", "totaltagv2b", "totaltagv2h"]}
            if name == "followon":
                columns = tags[F]
            else:
                fields = tags["F1" if F == "F3" else F]
                if name == "distant":
                    columns = [c for c in fields if c.endswith("b") or (D == "D2" and c.endswith("a"))]
                elif name == "incremental":
                    columns = [c for c in fields if c.endswith("h")]
                else:
                    raise ValueError(f"Unknown outcome {name}")
            result = p[columns].sum(axis=1, min_count=len(columns))
        self._outcomes[key] = result
        return result

    def sample(self, row, exclude=None):
        kind = row.get("sample") or "full"
        if kind == "full":
            ids = set(self.ids)
        elif kind == "boundary":
            ids = self.boundary[row.get("B") or "B1"].copy()
        elif kind == "timing":
            ids = self.timing.copy()
        else:
            raise ValueError(f"Unknown sample {kind}")
        if row["analysis"] == "AN13":
            ids &= set(self.density_decile.index[self.density_decile.eq(int(row["decile"]))])
        if exclude is not None:
            ids.discard(exclude)
        return ids

    def placebo(self, row):
        draw = self.draws.loc[(self.draws.seed == int(row["seed"])) & self.draws.fips.isin(self.ids)].copy()
        if draw.fips.duplicated().any() or set(draw.fips) != set(self.ids) or draw.u.isna().any():
            raise ValueError("Placebo seed requires exactly one nonmissing draw for every county in U")
        n = int(self.u.treat.sum())
        if row["variant"] == "placebo_perm":
            draw = draw.sort_values(["u", "fips"])
            draw["placebo_treat"] = (np.arange(len(draw)) < n).astype(int)
        else:
            draw["placebo_treat"] = (draw.u < n / len(self.u)).astype(int)
        return draw.set_index("fips").placebo_treat.sort_index()

    def model(self, row, exclude=None):
        """Return candidate observations, slopes, absorbed effects, reported terms."""
        a = row["analysis"]
        ids = self.sample(row, exclude)
        is_panel = a in ("AN03", "AN05", "AN08", "AN14") or (a == "AN13" and row["est"] == "M1")
        if is_panel or a == "AN11":
            cols = ["fips", "qidx", "year", "post", "treat"] + CONTROLS
            d = self.panel.loc[self.panel.fips.isin(ids), cols].copy()
            d["outcome"] = self.outcome(row["outcome"], row).loc[d.index]
            if a == "AN11":
                d = d.groupby(["fips", "year"], as_index=False).agg(outcome=("outcome", lambda s: s.sum(min_count=1)), treat=("treat", "first"))
                terms = [f"treat_year_{year}" for year in range(2005, 2015) if year != 2007]
                for year, term in zip([y for y in range(2005, 2015) if y != 2007], terms):
                    d[term] = d.treat * d.year.eq(year)
                effects, slopes = ["fips", "year"], terms.copy()
            else:
                term = "post_treat"
                treatment = d.treat
                if row.get("variant", "").startswith("placebo_"):
                    treatment = d.fips.map(self.placebo(row))
                    term = "post_placebo_treat"
                d[term] = d.post * treatment
                terms, slopes, effects = [term], [term], ["fips", "qidx"]
                if row.get("ctrl") == "1" or a in ("AN08", "AN14") or a == "AN13":
                    d[CONTROLS] = transformed_controls(d, row.get("L") or "L1")
                    slopes += CONTROLS
                if row.get("variant") == "dtt":
                    q = d.fips.map(self.density_quartile)
                    d["density_quarter"] = q * 10000 + d.qidx
                    effects = ["fips", "density_quarter"]
            d["y"] = transform(d.outcome, row.get("G") or "G1")
            return d, slopes, effects, terms

        if a not in ("AN04", "AN06", "AN07", "AN12", "AN13"):
            raise ValueError(f"Analysis {a} has no regression model")
        if a == "AN07":
            d = self.distance.loc[self.distance.fips.isin(ids)].copy()
            rule = row["W"]
            invalid = d.err.eq(0) if rule == "W1" else ((d.osrm_distance <= 0) | (d.ggl_distance <= 0)) if rule == "W4" else pd.Series(False, index=d.index)
            if exclude is None:
                self.log["by_spec"].setdefault(row["spec_id"], {})["distance_outcome_excluded"] = int(invalid.sum())
            d = d.loc[~invalid].copy()
            with np.errstate(divide="ignore", invalid="ignore"):
                d["y"] = np.log(d.err) if rule == "W1" else np.log1p(d.err) if rule == "W3" else abs(np.log(d.osrm_distance) - np.log(d.ggl_distance))
            terms = ["treat", "dist_km"]
        else:
            period = row.get("period") or "P0814"
            mask = self.panel.year.ge(2008) if period == "P0814" else self.panel.year.eq(2014 if period == "P14" else int(period[1:]))
            p = self.panel.loc[mask & self.panel.fips.isin(ids), ["fips"]].copy()
            p["outcome"] = self.outcome(row["outcome"], row).loc[p.index]
            d = p.groupby("fips").outcome.sum(min_count=1).reindex(sorted(ids)).rename("outcome").reset_index()
            d["y"] = transform(d.outcome, row.get("G") or "G1")
            terms = ["treat"]
        d["treat"] = d.fips.map(self.u.treat)
        cross = self.cross[row.get("Y") or "Y1"]
        controls = transformed_controls(cross, row.get("L") or "L1")
        for c in CONTROLS:
            d[c] = d.fips.map(controls[c])
        slopes = terms + CONTROLS
        qvars = ["population" if row.get("Q") == "Q2" else "popdensity", "income_householdmedian", "income_percapita"]
        reference = cross
        if row.get("R") == "R2":
            complete = np.isfinite(d[["y"] + slopes].to_numpy(dtype=float)).all(axis=1)
            reference = cross.reindex(sorted(d.loc[complete, "fips"].unique()))
        effects = []
        for c in qvars:
            effect = "quartile_" + c
            d[effect] = d.fips.map(groups(reference[c], 4))
            effects.append(effect)
        return d, slopes, effects, terms


def absorb_two(z, codes):
    """Orthogonal projection off two categorical effects by alternating means."""
    result = z.copy()
    counts = [np.bincount(c) for c in codes]
    for iteration in range(10000):
        old = result.copy()
        for c, count in zip(codes, counts):
            for j in range(result.shape[1]):
                mean = np.bincount(c, weights=result[:, j], minlength=len(count)) / count
                result[:, j] -= mean[c]
        if np.max(np.abs(result - old)) <= 1e-12:
            break
    else:
        raise ValueError("Fixed-effect absorption did not converge")
    n1, n2 = len(counts[0]), len(counts[1])
    edges = sparse.coo_matrix((np.ones(len(z)), (codes[0], n1 + codes[1])), shape=(n1 + n2, n1 + n2)).tocsr()
    ncomp = connected_components(edges, directed=False, return_labels=False)
    return result, n1 + n2 - ncomp


def fit_model(data, slopes, effects, terms, ci_hc1=False):
    needed = ["y", "fips"] + slopes + [e for e in effects if e != "fips"]
    good = np.isfinite(data[needed].to_numpy(dtype=float)).all(axis=1)
    d = data.loc[good]
    n = len(d)
    if not n:
        raise ValueError("No complete observations")
    counties = sorted(d.fips.unique())
    g = len(counties)
    if g <= 1:
        raise ValueError("Cluster inference requires at least two counties")
    y = d.y.to_numpy(dtype=float)
    x = d[slopes].to_numpy(dtype=float)
    scale = np.sqrt(np.mean(x*x, axis=0))
    scale[scale == 0] = 1
    yscale = max(float(np.sqrt(np.mean(y*y))), 1.0)
    z = np.column_stack([y / yscale, x / scale])
    codes = [pd.factorize(d[e], sort=True)[0] for e in effects]
    if len(effects) == 2:
        residualized, rank_fe = absorb_two(z, codes)
    else:
        # Small cross-section FE design: its numerical rank handles coincident
        # or empty quartile levels, including dependencies among three effects.
        fe = np.column_stack([np.ones(n)] + [(c[:, None] == np.arange(1, c.max() + 1)).astype(float) for c in codes])
        u, s, _ = linalg.svd(fe, full_matrices=False)
        rank_fe = int(np.sum(s > s[0] * max(fe.shape) * np.finfo(float).eps))
        basis = u[:, :rank_fe]
        residualized = z - basis @ (basis.T @ z)
    yw, xw = residualized[:, 0] * yscale, residualized[:, 1:]
    norm = np.linalg.norm(xw, axis=0)
    active = norm > 1e-10 * np.sqrt(n)
    term_idx = [slopes.index(t) for t in terms]
    if not all(active[i] for i in term_idx):
        raise ValueError("Focal regressor absorbed or constant")
    active_idx = np.flatnonzero(active)
    xa = xw[:, active] / norm[active]
    u, s, vt = linalg.svd(xa, full_matrices=False)
    rank_x = int(np.sum(s > max(xa.shape) * np.finfo(float).eps * s[0] * 10))
    # A focal coefficient must be unique even if nuisance regressors are aliased.
    if rank_x < xa.shape[1]:
        null = vt[rank_x:]
        for i in term_idx:
            loc = int(np.flatnonzero(active_idx == i)[0])
            if np.linalg.norm(null[:, loc]) > 1e-8:
                raise ValueError("Focal regressor not identified (rank-deficient slopes)")
    k_all = rank_fe + rank_x
    if n <= k_all:
        raise ValueError(f"Nonpositive residual degrees of freedom: N={n}, K={k_all}")
    # bread maps residualized observations to coefficients in normalized units.
    bread = (vt[:rank_x].T / s[:rank_x]) @ u[:, :rank_x].T
    beta = bread @ yw
    residual = yw - xa @ beta
    scores = bread * residual
    cluster_code = pd.factorize(d.fips, sort=True)[0]
    cluster_scores = np.column_stack([np.bincount(cluster_code, weights=v, minlength=g) for v in scores])
    var_cluster = np.sum(cluster_scores**2, axis=0) * (g / (g - 1)) * ((n - 1) / (n - rank_x))
    var_hc1 = np.sum(scores**2, axis=1) * n / (n - k_all)
    denom = scale[active] * norm[active]
    beta, sec, seh = beta / denom, np.sqrt(var_cluster) / denom, np.sqrt(var_hc1) / denom
    sst = float(np.sum((y - y.mean())**2))
    r2 = 1 - float(residual @ residual) / sst if sst > 0 else np.nan
    rows = []
    for term, i in zip(terms, term_idx):
        j = int(np.flatnonzero(active_idx == i)[0])
        with np.errstate(divide="ignore", invalid="ignore"):
            pc = float(2 * stats.t.sf(abs(beta[j] / sec[j]), g - 1))
            ph = float(2 * stats.t.sf(abs(beta[j] / seh[j]), n - k_all))
        critical = stats.t.ppf(.975, n - k_all if ci_hc1 else g - 1)
        se = seh[j] if ci_hc1 else sec[j]
        rows.append(dict(term=term, status="ok", error="", n_obs=n, n_counties=g,
                         n_dropped_missing=int((~good).sum()), estimate=float(beta[j]),
                         se_cluster=float(sec[j]), p_cluster=pc, df_cluster=g - 1,
                         se_hc1=float(seh[j]), p_hc1=ph, df_hc1=n - k_all,
                         ci_low=float(beta[j] - critical * se), ci_high=float(beta[j] + critical * se),
                         r2=r2, k_slopes=rank_x, sample_hash=sample_hash(counties)))
    return rows, counties


def descriptive(data, row, tables):
    a, sid = row["analysis"], row["spec_id"]
    p = data.panel
    base = dict(status="ok", error="", n_obs=len(p), n_counties=len(data.ids),
                n_dropped_missing=0, sample_hash=sample_hash(data.ids))
    result = []
    if a == "AN01":
        county = data.u.copy()
        for name in ["total", "followon", "contributors", "owner"]:
            county[name] = data.outcome(name, row).groupby(p.fips).mean()
        county["err_mean"] = data.distance.groupby("fips").err.mean()
        for c in ["population", "households", "unemploymentrate", "popeduc", "popmales", "popyoungmales", "income_percapita"]:
            county["change_" + c] = p.loc[p.year.eq(2014)].groupby("fips")[c].first() - p.loc[p.year.eq(2005)].groupby("fips")[c].first()
        for var in county.columns.drop("treat"):
            t, c = county.loc[county.treat.eq(1), var].dropna(), county.loc[county.treat.eq(0), var].dropna()
            diff = t.mean() - c.mean()
            tables["an01_groups"].append(dict(spec_id=sid, variable=var, treated_mean=t.mean(), control_mean=c.mean(),
                difference=diff, n_treated=len(t), n_control=len(c),
                p_welch=stats.ttest_ind(t, c, equal_var=False).pvalue if len(t) > 1 and len(c) > 1 else np.nan,
                p_equal_variance=stats.ttest_ind(t, c, equal_var=True).pvalue if len(t) > 1 and len(c) > 1 else np.nan))
            result.append(dict(base, term=var, estimate=diff, n_obs=len(t)+len(c), n_counties=len(t)+len(c),
                               n_dropped_missing=len(county)-len(t)-len(c), sample_hash=sample_hash(list(t.index)+list(c.index))))
    elif a == "AN02":
        outcomes = ["total", "followon", "contributors", "distant", "incremental", "new", "old", "low_own", "high_own", "owner"]
        for var in outcomes + ["treat", "post", "year", "qidx", "population", "households", "popdensity", "income_percapita"]:
            v = data.outcome(var, row) if var in outcomes else p[var]
            tables["an02_summary"].append(dict(spec_id=sid, variable=var, mean=v.mean(), std=v.std(ddof=1),
                median=v.median(), min=v.min(), max=v.max(), n_nonmissing=v.count(), n_rows=len(p),
                n_counties=len(data.ids), n_quarters=p.qidx.nunique()))
            result.append(dict(base, term=var, estimate=v.mean(), n_dropped_missing=int(v.isna().sum())))
    elif a == "AN09":
        for fips, record in data.u.iterrows():
            tables["an09_membership"].append(dict(spec_id=sid, fips=fips, treat=record.treat,
                boundary_B1=int(fips in data.boundary["B1"]), boundary_B2=int(fips in data.boundary["B2"]), timing=int(fips in data.timing)))
        for name, ids in [("full", set(data.ids)), ("boundary_B1", data.boundary["B1"]), ("boundary_B2", data.boundary["B2"]), ("timing", data.timing)]:
            for t in [0, 1]:
                tables["an09_counts"].append(dict(spec_id=sid, sample=name, treat=t, n_counties=int(data.u.loc[sorted(ids), "treat"].eq(t).sum())))
        result.append(dict(base, term="membership", n_obs=len(data.ids)))
    elif a == "AN10":
        for outcome in ["total", "followon"]:
            d = p[["fips", "qidx", "quarter", "treat"]].copy()
            v = data.outcome(outcome, row)
            d["log1p"] = transform(v, "G1")
            d["cumulative"] = v.groupby(p.fips).cumsum()
            table = d.groupby(["qidx", "quarter", "treat"], as_index=False).agg(mean_log1p=("log1p", "mean"), mean_cumulative=("cumulative", "mean"), n_counties=("fips", "nunique"))
            table["spec_id"], table["outcome"] = sid, outcome
            tables["an10_means"].extend(table.to_dict("records"))
            result.append(dict(base, term=outcome))
    else:
        raise ValueError(f"Unknown descriptive analysis {a}")
    return result


def write_outputs(out, results, tables, log, influence=None):
    pd.DataFrame(results, columns=RESULT_COLS).to_csv(out / "results.csv", index=False)
    for name, columns in TABLE_COLS.items():
        pd.DataFrame(tables[name], columns=columns).to_csv(out / (name + ".csv"), index=False)
    (out / "prep_log.json").write_text(json.dumps(log, indent=2, default=lambda x: x.item() if isinstance(x, np.generic) else str(x)) + "\n")
    if influence is not None:
        columns = ["spec_id", "analysis", "fips", "term", "status", "error", "n_obs", "n_counties", "n_dropped_missing", "estimate", "se_cluster", "p_cluster", "df_cluster", "se_hc1", "p_hc1", "df_hc1", "sample_hash"]
        pd.DataFrame(influence, columns=columns).to_csv(out / "influence.csv", index=False)
    versions = ["Python " + platform.python_version(), "Platform " + platform.platform()]
    for package in ["numpy", "pandas", "scipy", "statsmodels", "linearmodels", "pyfixest", "pyreadstat", "openpyxl"]:
        try:
            versions.append(package + " " + importlib.metadata.version(package))
        except importlib.metadata.PackageNotFoundError:
            versions.append(package + " unavailable")
    (out / "session_info.txt").write_text("\n".join(versions) + "\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("data_dir", type=Path)
    parser.add_argument("output_dir", type=Path)
    parser.add_argument("--influence")
    args = parser.parse_args()
    args.output_dir.mkdir(parents=True, exist_ok=True)
    grid = pd.read_csv(io.StringIO(GRID_CSV), dtype=str, keep_default_na=False)
    if args.influence:
        grid = grid.loc[grid.spec_id.eq(args.influence)]
        if grid.empty:
            parser.error("Unknown influence spec_id")
    tables = {name: [] for name in TABLE_COLS}
    results, influence = [], [] if args.influence else None
    start = time.monotonic()
    try:
        data = Data(args.data_dir)
    except Exception as exc:
        log = {"preparation_error": str(exc), "traceback": traceback.format_exc()}
        for row in grid.to_dict("records"):
            results.append(dict(spec_id=row["spec_id"], analysis=row["analysis"], status="failed", error="Data preparation: " + str(exc)))
        write_outputs(args.output_dir, results, tables, log, influence)
        return
    for number, row in enumerate(grid.to_dict("records"), 1):
        prefix = dict(spec_id=row["spec_id"], analysis=row["analysis"])
        try:
            if row["analysis"] in ("AN01", "AN02", "AN09", "AN10"):
                if args.influence:
                    raise ValueError("Influence mode requires a regression specification")
                fitted = descriptive(data, row, tables)
            else:
                if row["variant"].startswith("placebo_"):
                    vector = data.placebo(row)
                    tables["placebo_vectors"].extend(dict(spec_id=row["spec_id"], fips=int(c), placebo_treat=int(t)) for c, t in vector.items())
                model = data.model(row)
                fitted, counties = fit_model(*model, ci_hc1=row["analysis"] == "AN12")
                if args.influence:
                    focal = model[3][0]
                    for county in counties:
                        try:
                            refits, _ = fit_model(*data.model(row, exclude=county), ci_hc1=row["analysis"] == "AN12")
                            refit = next(r for r in refits if r["term"] == focal)
                            influence.append(dict(prefix, fips=int(county), **refit))
                        except Exception as exc:
                            influence.append(dict(prefix, fips=int(county), term=focal, status="failed", error=str(exc)))
            results.extend(dict(prefix, **r) for r in fitted)
        except Exception as exc:
            results.append(dict(prefix, status="failed", error=str(exc)))
        if number % 100 == 0:
            print(f"Completed {number}/{len(grid)} specifications ({time.monotonic()-start:.1f}s)", file=sys.stderr)
    data.log["elapsed_seconds"] = time.monotonic() - start
    data.log["grid_rows_requested"] = len(grid)
    data.log["grid_rows_failed"] = len({r["spec_id"] for r in results if r["status"] == "failed"})
    data.log["grid_sha256"] = hashlib.sha256(GRID_CSV.encode()).hexdigest()
    write_outputs(args.output_dir, results, tables, data.log, influence)


